import re

def solve(env, goal):
    def obs():
        return env.observation

    def parse_goal(goal):
        g = goal.strip().lower().rstrip('.')
        m = re.match(r'put (?:a |an |the )?(\w+(?: \w+)?) (?:in|on|to) (\w+ ?\d*)', g)
        if m:
            return m.group(1), m.group(2)
        return None, None

    def find_object(text):
        # find "a potato 1" style mentions in observation
        return None

    def clean_name(s):
        return s.strip().lower()

    target_obj, target_rec = parse_goal(goal)

    # locate target object among visible objects, go to its receptacle
    def locate_and_take(obj_name):
        # obj_name like "potato" or "cool potato"? goal says "a cool potato" -> object potato, state cool
        base = obj_name
        for w in ["cool", "hot", "clean", "dirty", "cooked", "raw"]:
            if base.startswith(w + " "):
                base = base[len(w)+1:]
        # search receptacles by visiting? We can use current obs and go-to each listed receptacle.
        # First check current obs text for the object.
        ob = obs()
        if re.search(r'\b' + re.escape(base) + r'(?: \d+)?\b', ob, re.I):
            # try take from current location
            loc = None
            m = re.search(r'You are in the ([a-z ]+?)(?:\.|,|$)', ob, re.I)
            if m:
                loc = m.group(1).strip()
            if loc:
                fb = env.step(f"take {base} 1 from {loc}")
                if "pick up" in fb.lower() or "you pick" in fb.lower():
                    return True
        return False

    # Gather receptacle list from initial observation
    init = env.observation
    receptacles = []
    for m in re.finditer(r'\b([a-z]+(?: [a-z]+)? \d+)\b', init):
        receptacles.append(m.group(1))

    # Deduplicate while keeping order
    seen = set()
    recs = []
    for r in receptacles:
        rl = r.lower()
        if rl not in seen:
            seen.add(rl)
            recs.append(r)

    base_obj = target_obj
    for w in ["cool", "hot", "clean", "dirty", "cooked", "raw"]:
        if base_obj.startswith(w + " "):
            base_obj = base_obj[len(w)+1:]

    # If already visible in current obs, take it
    taken = False
    ob = obs()
    if re.search(r'\b' + re.escape(base_obj) + r'(?: \d+)?\b', ob, re.I):
        locm = re.search(r'You are (?:in|at) (?:the )?([a-z0-9 ]+?)(?:\.|,|$)', ob, re.I)
        loc = locm.group(1).strip() if locm else None
        if loc:
            fb = env.step(f"take {base_obj} 1 from {loc}")
            if "pick" in fb.lower():
                taken = True

    if not taken:
        for r in recs:
            if r.lower() == target_rec.lower():
                continue
            fb = env.step(f"go to {r}")
            ob = obs()
            m = re.search(r'\b' + re.escape(base_obj) + r'(?: \d+)?\b', ob, re.I)
            if m:
                # take the first matching full name
                full = m.group(0)
                fb = env.step(f"take {full} from {r}")
                if "pick" in fb.lower():
                    taken = True
                    break

    if not taken:
        return False

    # Now perform cooling if needed
    ob = obs()
    if target_obj.startswith("cool "):
        # go to fridge
        fridge = None
        for r in recs:
            if r.lower().startswith("fridge"):
                fridge = r
                break
        if fridge:
            fb = env.step(f"go to {fridge}")
            ob = obs()
            m = re.search(r'\b' + re.escape(base_obj) + r'(?: \d+)?\b', ob, re.I)
            full = m.group(0) if m else base_obj + " 1"
            fb = env.step(f"cool {full} with {fridge}")
            ob = obs()

    # Move to target receptacle
    fb = env.step(f"go to {target_rec}")
    ob = obs()
    m = re.search(r'\b' + re.escape(base_obj) + r'(?: \d+)?\b', ob, re.I)
    full = m.group(0) if m else base_obj + " 1"
    fb = env.step(f"move {full} to {target_rec}")
    return True
